package glitch

import data.glitch_lib

# Credential-related keywords that indicate potential hard-coded credentials
credential_keywords := {
    # Inbound Authentication
    "admin_user", "admin_username", "root_user", "default_user", "service_account",
    "admin_pass", "admin_password", "root_pass", "root_password", "default_password",
    "password", "passwd", "pwd", "pass",
    # Outbound Authentication
    "connection_string", "db_password", "database_password", "api_key", "api_secret",
    "access_key", "secret_key", "auth_token", "bearer_token", "private_key",
    "service_principal", "client_secret", "tenant_id",
    # Database Connections
    "jdbc_url", "postgres_url", "mysql_host", "redis_host", "mongodb_uri",
    "username", "user",
    # Cloud Service Connections
    "provider_credentials", "subscription_id", "account_id",
    "secret_access_key", "session_token", "shared_key",
    # Cryptographic Material
    "encryption_key", "decryption_key", "signing_key", "hmac_key", "aes_key",
    "symmetric_key", "master_key", "kms_key_id",
    "certificate", "cert_pem", "key_pem", "ca_cert", "tls_key",
    # Secret Storage
    "secret", "secure_string", "sensitive", "confidential",
    # Container and Orchestration
    "image_pull_secret", "registry_password", "docker_config",
    "basic_auth", "htpasswd", "dockerhub_token",
    # Virtual Machine and Compute
    "admin_password", "computer_name", "os_profile",
    # Network and Security
    "vpn_shared_key", "ipsec_secret", "preshared_key", "psk",
    # Identity and Access Management
    "initial_password", "force_password_change", "require_secure_password",
    # Role and Permission
    "assume_role", "role_arn"
}

# Check if a value is a literal string (not a reference)
is_literal_string(value) {
    value.ir_type == "String"
    value.value != ""
    not looks_like_reference(value.value)
}

# Check if a value looks like a reference to external secret management
looks_like_reference(value) {
    contains(lower(value), "data.")
} else {
    contains(lower(value), "var.")
} else {
    contains(lower(value), "vault")
} else {
    contains(lower(value), "secret_id")
} else {
    contains(lower(value), "random_")
} else {
    contains(lower(value), "uuid")
} else {
    contains(lower(value), "timestamp")
}

# Check for high-entropy patterns suggesting API keys or tokens
is_high_entropy_string(value) {
    # Base64-like pattern
    regex.match("^[A-Za-z0-9+/]{20,}={0,2}$", value)
} else {
    # Hex-like pattern
    regex.match("^[0-9a-fA-F]{32,}$", value)
}

# Check if a string contains embedded credentials in URL format
has_embedded_creds(value) {
    regex.match("^[a-zA-Z]+://[^:]+:[^@]+@", value)
}

# Check for common weak password patterns
is_weak_password(value) {
    regex.match("(?i)^(password|admin|root|123456|secret|default|test|user|login|qwerty|letmein)$", value)
} else {
    count(value) < 12
}

# Recursively check if a value contains any variable references
contains_variable_ref(value) {
    value.ir_type == "VariableReference"
} else {
    value.ir_type == "FunctionCall"
} else {
    value.ir_type == "MethodCall"
} else {
    walk(value, [_, n])
    n.ir_type == "VariableReference"
}

# Check value for hard-coded credentials
has_hardcoded_credential(value) {
    # Direct string with credential indicators
    value.ir_type == "String"
    is_high_entropy_string(value.value)
} else {
    value.ir_type == "String"
    has_embedded_creds(value.value)
}

# Main analysis for Attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check if attribute name indicates credential field
    is_credential_field(attr.name)

    # Check for literal string value
    is_literal_string(attr.value)

    # Check for hardcoded credential patterns or weak passwords
    hardcoded_credential_check(attr.value)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Credentials should not be hard-coded in configuration files. Use external secret management instead. (CWE-798)"
    }
}

# Check for Variables with hard-coded credentials
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    v := vars[_]

    # Check if variable name indicates credential field
    is_credential_field(v.name)

    # Check for literal string value
    is_literal_string(v.value)

    # Check for hardcoded credential patterns or weak passwords
    hardcoded_credential_check(v.value)

    result := {
        "type": "sec_hard_secr",
        "element": v,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Credentials should not be hard-coded in configuration files. Use external secret management instead. (CWE-798)"
    }
}

# Check for disable_password_authentication set to false (indicating password reliance)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr.name == "disable_password_authentication"
    attr.value.ir_type == "Boolean"
    attr.value.value == false

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Password authentication enabled - disable_password_authentication is set to false, indicating reliance on password-based authentication. Consider using key-based authentication instead. (CWE-798)"
    }
}

# Check for force_password_change set to false
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

