        "element": attr,
        "path": parent.path,
        "description": "Password change not forced - force_password_change is set to false, allowing initial passwords to persist. (CWE-798)"
    }
}

# Helper: Check if field name indicates credential-related field
is_credential_field(name) {
    lower_name := lower(name)
    kw := credential_keywords[_]
    contains(lower_name, kw)
}

# Helper: Check for various hardcoded credential indicators
hardcoded_credential_check(value) {
