package glitch

import data.glitch_lib

credential_keywords := {
    "password", "passwd", "pwd", "secret", "secret_key", "access_key", "api_key",
    "api_secret", "auth_token", "bearer_token", "private_key", "client_secret",
    "connection_string", "encryption_key", "hmac_key", "aes_key", "signing_key",
    "master_key", "kms_key_id", "tls_key", "key_pem", "cert_pem", "ca_cert",
    "pre_shared_key", "preshared_key", "psk", "shared_key", "vpn_key"
}

password_hash_patterns := ["sha512_password", "pbkdf2_password", "md5_password", "sha256_password"]

is_literal_string_value(value) {
    value.ir_type == "String"
    value.value != ""
    not looks_like_reference(value.value)
}

looks_like_reference(v) {
    contains(lower(v), "vault")
} else {
    contains(lower(v), "secret_")
} else {
    contains(lower(v), "random_")
} else {
    contains(lower(v), "uuid")
} else {
    contains(lower(v), "timestamp")
} else {
    regex.match("\\{\\{.*\\}\\}", v)
} else {
    regex.match("\\$\\{.*\\}", v)
} else {
    regex.match("^\\s*data\\.", v)
} else {
    regex.match("^\\s*var\\.", v)
}

is_high_entropy_or_hash(value) {
    regex.match("^[A-Za-z0-9+/]{20,}={0,2}$", value)
} else {
    regex.match("^[0-9a-fA-F]{32,}$", value)
} else {
    regex.match("^\\$[0-9a-zA-Z]+\\$", value)
} else {
    regex.match("^\\$6\\$", value)
}

is_credential_field_name(name) {
    lower_name := lower(name)
    some kw in credential_keywords
    contains(lower_name, kw)
} else {
    some pw in password_hash_patterns
    contains(lower(name), pw)
}

# Recursively search for credential fields in nested structures
find_credential_in_value(key, value) {
    is_credential_field_name(key)
    is_literal_string_value(value)
} else {
    is_credential_field_name(key)
    value.ir_type == "String"
    is_high_entropy_or_hash(value.value)
} else {
    value.ir_type == "Hash"
    some entry in value.value
    find_credential_in_value(entry.key.value, entry.value)
} else {
    value.ir_type == "Array"
    some elem in value.value
    find_credential_in_value(key, elem)
}

# For Variable with Hash value - need to check nested structure
check_variable_for_credential(var) {
    var.value.ir_type == "Hash"
    some entry in var.value.value
    find_credential_in_value(entry.key.value, entry.value)
} else {
    # Direct credential field name check
    is_credential_field_name(var.name)
    var.value.ir_type == "String"
    var.value.value != ""
    not looks_like_reference(var.value.value)
}

# Check if this is a hash structure containing credential fields
hash_contains_credential(hash) {
    hash.ir_type == "Hash"
    some entry in hash.value
    is_credential_field_name(entry.key.value)
    entry.value.ir_type == "String"
    entry.value.value != ""
    not looks_like_reference(entry.value.value)
}

